test-case.test:
copy $c := <a>AA<b/>CC</a>
modify delete node $c/b
return ($c, count($c/text()))

copy $c := <a>United States</a>
modify insert node 'foo' as last into $c
return (count($c/text()), string($c))

copy $c := <a>United States</a>
modify insert node 'foo' into $c
return count($c/text())

copy $c := <location>US</location>
modify insert node 'foo' before $c/text()
return (count($c/text()), string($c))

copy $c := <location>US</location>
modify insert node 'foo' after $c/text()
return (count($c/text()), string($c))

copy $c := <n>aa<d/><d/>cc</n>
modify (
  delete node $c/d,
  insert node 'bb' after $c/d[1]
)
return (count($c/text()), $c/text())

copy $c := <n>aa<d/><d/>cc</n>
modify (
  delete node $c/d,
  insert node 'bb' before $c/d[2]
)
return (count($c/text()), string($c))

copy $c := <a>shouldBe<Single/>TextNode</a>
modify replace node $c/Single with 'Single'
return ($c, count($c/text()))

copy $c := <n>a<b/>c</n>
modify replace value of node $c/b with 'x'
return count($c/text())

copy $c := <n>a<b/>c</n>
modify insert node ('', '') before $c/b
return count($c/text())

copy $c := <n><b/></n>
modify insert node text { '' } into $c
return count($c/node())

copy $c := <n>a</n>
modify replace node $c/text() with text { '' }
return count($c/node())

copy $c := <a>x<b/>y</a>
modify replace node $c/b with ('1', <c/>, '2')
return (count($c/text()), string($c))

copy $c := <a>x<b/>y</a>
modify replace node $c/b with text { '1' }
return (count($c/text()), string($c))

copy $c := <a>x<b/>y</a>
modify rename node $c/b as 'c'
return count($c/text())
